import{z as S,x as T,o,c as E,q as A,j as s,D as l,d as r,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"SAT 与 3-SAT","description":"","frontmatter":{"title":"SAT 与 3-SAT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sat-3sat.md","filePath":"cs/sat-3sat.md","lastUpdated":1791063341000}'),d={name:"cs/sat-3sat.md"};function p(C,a,B,_,P,h){const t=T("Mermaid");return o(),E("div",null,[a[2]||(a[2]=A('<h1 id="sat-与-3-sat" tabindex="-1">SAT 与 3-SAT <a class="header-anchor" href="#sat-与-3-sat" aria-label="Permalink to &quot;SAT 与 3-SAT&quot;">​</a></h1><div class="epigraph"><p>命题可满足性是 NP 完全的根；每个子句至多三个文字的 3-SAT 仍完全，两个文字的 2-SAT 却在 P。</p><footer>—— 据 Cook, The Complexity of Theorem-Proving Procedures, 1971；Levin, 1973；Karp, 1972 整理</footer></div><p>上一课<a href="/cs/npc-canonical">NPC 典型问题</a>已经把 SAT 当作 Cook–Levin 的第一块，并把 3-SAT、覆盖、哈密顿列入脸谱。本课不重列 Karp 清单。缺口是把<strong>布尔公式</strong>写成课程对象：CNF、文字、子句；SAT 为何够当根；如何把任意 CNF 垫成 3-SAT 而不离开 NP 完全；对照 2-SAT 的蕴含图。后课在 NP 完全的墙外谈近似。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SAT：命题变元、合取范式 \\(\\bigwedge_i \\bigvee_j \\ell_{ij}\\)，问是否存在赋值使整式为真。证书是赋值，验证扫一遍子句，故在 NP。Cook–Levin：任意 NP 语言的验证器可在多项式时间编成一份 SAT 实例（计算表格）。本课不把表格构造写完，只锁定「先 SAT，再归约」。</p><p>子句长度不限时叫 SAT（或 CNF-SAT）。每子句恰三文字：3-SAT。长子句 \\((\\ell_1\\lor\\cdots\\lor\\ell_k)\\) 引入新变元拆成 \\((\\ell_1\\lor\\ell_2\\lor y_1)\\land(\\neg y_1\\lor\\ell_3\\lor y_2)\\land\\cdots\\)，可满足性等价，多项式规模。故 3-SAT 仍 NPC。1-SAT、霍恩子句等另当别论。</p><h3 id="_3-不是「再难一点的-2」" tabindex="-1">3 不是「再难一点的 2」 <a class="header-anchor" href="#_3-不是「再难一点的-2」" aria-label="Permalink to &quot;3 不是「再难一点的 2」&quot;">​</a></h3><p>2-SAT：每子句两文字。建蕴含图：\\(\\ell_1\\lor\\ell_2\\) 变成 \\(\\neg\\ell_1\\Rightarrow\\ell_2\\) 与 \\(\\neg\\ell_2\\Rightarrow\\ell_1\\)。强连通分量里若某变元与其否定同块则不可满足，否则可线性赋值。<a href="/cs/bcc-bridge">连通分量与桥</a>的 SCC 在这里变成多项式算法。完全性在第三个文字处出现，不是连续变难。</p><p><span class="marginnote">Cook 1971（北美）；Levin 同期独立（表格与「universal search」）。Karp 1972 把 3-SAT 列为 21 题之一。Garey/Johnson 收录标准型。本课要拆句与 2-SAT 对照，不重画图灵机纸带。</span></p><p><span class="marginnote">「拆句」就是把长子句垫上新变元压到三文字：\\((\\ell_1\\lor\\ell_2\\lor\\ell_3\\lor\\ell_4)\\) 变成 \\((\\ell_1\\lor\\ell_2\\lor y)\\land(\\neg y\\lor\\ell_3\\lor\\ell_4)\\)——只要原四项有一个真，总能选对 \\(y\\) 让两个新子句同时真，反之亦然，可满足性等价。</span></p><p><span class="marginnote">常见误区：初学者容易以为「约束从两个文字变三个文字只是量变」。实际上 2-SAT 的蕴含图每条边是确定性的（一个取值强制另一个），沿图走就行；第三个文字引入了「二选一分支」，组合爆炸从这里进来，复杂度等级在这一点上跳变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>认 CNF。证 3-SAT 在 NP（赋值仍短）。给 SAT \\(\\le_p\\) 3-SAT 的拆句。点名：电路 SAT、HORNSAT 的位置不展开。画 2-SAT 蕴含边，声明用 SCC，不手跑例子到完。</p>',13)),(o(),s(i,null,{default:l(()=>[n(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NP%5B%22%E4%BB%BB%E6%84%8F%20NP%22%5D%20--%3E%20SAT%5B%22SAT%20%2F%20CNF%22%5D%0A%20%20SAT%20--%3E%20T3%5B%22%E6%8B%86%E5%8F%A5%20%E2%86%92%203-SAT%22%5D%0A%20%20SAT%20--%3E%20T2%5B%222-SAT%EF%BC%9A%E8%95%B4%E5%90%AB%E5%9B%BE%20%2B%20SCC%20%E2%88%88%20P%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/np-reduction"},"多项式归约"),r("的方向：要证 3-SAT 完全，从已完全的 SAT 归约到它，再从 3-SAT 出发构造图问题。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"后课近似、随机化常以 3-SAT 或顶点覆盖为源。编译器不在本课解 SAT；类型与语法分析停在 P 里的受限文法。不要把 SAT 求解器的 CDCL 写成多项式算法。",-1)),a[6]||(a[6]=e("p",null,"量化布尔（QBF）是 PSPACE 完全的另一层，本课不启用。",-1)),(o(),s(i,null,{default:l(()=>[n(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20CL%5B%22%E5%AD%90%E5%8F%A5%20l1%20%E2%88%A8%20l2%22%5D%20--%3E%20IMP1%5B%22%C2%ACl1%20%E2%87%92%20l2%22%5D%0A%20%20CL%20--%3E%20IMP2%5B%22%C2%ACl2%20%E2%87%92%20l1%22%5D%0A%20%20IMP1%20--%3E%20GRAPH%5B%22%E8%95%B4%E5%90%AB%E5%9B%BE(%E6%AF%8F%E5%8F%98%E5%85%83%E6%AD%A3%E5%8F%8D%E4%B8%A4%E7%BB%93%E7%82%B9)%22%5D%0A%20%20IMP2%20--%3E%20GRAPH%0A%20%20GRAPH%20--%3E%20SCC%7B%22x%20%E4%B8%8E%20%C2%ACx%20%E5%90%8C%E4%B8%80%20SCC%3F%22%7D%0A%20%20SCC%20--%20%22%E5%90%8C%E5%9D%97%22%20--%3E%20UNSAT%5B%22%E4%B8%8D%E5%8F%AF%E6%BB%A1%E8%B6%B3%22%5D%0A%20%20SCC%20--%20%22%E4%B8%8D%E5%90%8C%E5%9D%97%22%20--%3E%20ASSIGN%5B%22%E6%8C%89%20SCC%20%E6%8B%93%E6%89%91%E5%BA%8F%E7%BA%BF%E6%80%A7%E8%B5%8B%E5%80%BC%2C%20%E5%8F%AF%E6%BB%A1%E8%B6%B3%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p>这张图回答的问题是：2-SAT 为什么能在多项式时间判定——每个双子句变成两条确定的蕴含边，判定问题就化成图论问题「变元与其否定是否同处一个强连通分量」，与 3-SAT 的指数搜索形成对照。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Cook–Levin 表格。不引入 PCP、近似硬度。后课默认：3-SAT 是 NPC 根上的标准型；2-SAT 在 P。精确解指数时，下一课谈近似比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SAT 在 NP 且 NP-难（Cook–Levin）；3-SAT 由拆句保持完全。</li><li>2-SAT 走蕴含图，不在 NPC。</li><li>后课图问题的 gadget 默认从 3-SAT 出发。</li><li>出处：Cook, 1971；Levin, 1973；Karp, 1972。</li></ul>',5))])}const u=S(d,[["render",p]]);export{m as __pageData,u as default};
